pub enum EntityIngestionError {
    /// Errors related to the parliament API
    #[error("error when retrieving data from the parliament API: {0}")]
    ApiError(#[from] ParliamentApiError),

    /// Generic error related to entity parsing, cleaning and resolution
    #[error("error in ingestion pipeline: {0}")]
    DataError(String),

    /// Failure reading or writing ingestion storage.
    #[error("ingestion storage failed: {0}")]
    IoError(#[from] EntitySearchPipelineError),

    /// Invalid stage
    #[error("invalid stage provided: {0}")]
    InvalidStage(String),

    /// Invalid stage
    #[error("invalid ingestion ID: {0}")]
    UnvalidIngestionId(String),

    /// Generic error
    #[error("unexpected error occured: {0}")]
    UnexpectedError(String),
}

/// Whether public address evidence supports the conservative automatic-link rule.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum AddressMatchQuality {
    /// No usable public-address text.
    #[default]
    Unavailable,
    /// Public text lacks a numbered street address.
    Partial,
    /// A house or building number and a street designation are both present.
    NumberedStreet,
}
impl AddressMatchQuality {
    pub(crate) fn from_normalized(address: Option<&str>) -> Self {
        let Some(address) = address else {
            return Self::Unavailable;
        };
        let tokens = address
            .split_whitespace()
            .map(|token| token.trim_matches(|c: char| !c.is_alphanumeric()))
            .collect::<Vec<_>>();
        let number = tokens.iter().any(|token| {
            token.as_bytes().first().is_some_and(u8::is_ascii_digit)
                && token.bytes().all(|c| c.is_ascii_alphanumeric())
                && token.bytes().filter(u8::is_ascii_alphabetic).count() <= 1
        });
        let street = tokens.iter().any(|token| {
            matches!(
                *token,
                "road"
                    | "rd"
                    | "street"
                    | "st"
                    | "avenue"
                    | "ave"
                    | "lane"
                    | "drive"
                    | "way"
                    | "place"
                    | "close"
                    | "terrace"
                    | "court"
                    | "crescent"
                    | "square"
                    | "gardens"
                    | "park"
                    | "mews"
                    | "boulevard"
                    | "row"
            )
        });
        if number && street {
            Self::NumberedStreet
        } else {
            Self::Partial
